begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();request uuid:=gen_random_uuid();review uuid:=gen_random_uuid();r jsonb;body jsonb;starter jsonb:=$starter${"version":1,"coins":250,"level":1,"xp":0,"rep":0,"active":"willow","farms":{"willow":{"layoutVersion":2,"gridScaleVersion":2,"cropClusterVersion":1,"tileSizeVersion":1,"fixedGridVersion":1,"objects":[{"id":"p1","type":"plot","x":4,"y":3,"crop":"carrot","stage":0,"plantedAt":0},{"id":"p2","type":"plot","x":5,"y":3,"crop":"wheat","stage":0,"plantedAt":0},{"id":"p3","type":"plot","x":4,"y":4,"crop":"strawberry","stage":0,"plantedAt":0},{"id":"orchard-main","type":"orchard","x":9,"y":2,"tier":0,"lastFruitAt":1793385794570},{"id":"b1","type":"coop","x":3,"y":1,"tier":0},{"id":"t1","type":"tree","x":1,"y":2,"lastFruitAt":1793385794570},{"id":"f1","type":"flowers","x":6,"y":2,"plantedAt":1793385794570},{"id":"w1","type":"well","x":1,"y":5,"tier":0,"helpers":{"jade":false,"rhys":false,"jay":false},"helperCrop":"carrot","helperPlantMode":"previous","helperCropCap":0},{"id":"a1","type":"chicken","x":3,"y":1,"name":"Pip","coopId":"b1","hunger":79,"clean":84,"happy":81,"lastCare":1793385794570,"needsAt":1793385794570,"lastProductAt":1793385794570}],"storage":[],"inventory":{"carrot":5,"wheat":3,"strawberry":2,"corn":0,"tomato":0,"lavender":0,"pumpkin":0,"apple":0,"mushroom":0,"egg":1,"milk":0},"orders":[{"id":"order-willow-1","name":"Mara the Baker","emoji":"👩‍🍳","ask":{"wheat":3,"carrot":2},"reward":75,"rep":16,"hello":"Mara is baking for the village picnic.","vendor":"mara"},{"id":"order-willow-2","name":"Jun the Jam Maker","emoji":"🧑‍🍳","ask":{"strawberry":3,"carrot":2},"reward":105,"rep":20,"hello":"Jun has a batch of jars ready to fill.","vendor":"jun"},{"id":"order-willow-3","name":"Tavi from the Co-op","emoji":"🧑‍🌾","ask":{"corn":3,"wheat":2},"reward":90,"rep":18,"hello":"Tavi is stocking the village pantry.","vendor":"tavi"}],"done":0,"visits":0,"shop":{"unlocked":false,"stock":{},"earned":0},"expanded":false,"expansionLevel":0,"helperStamina":{"jade":{"jobs":0,"drinkUntil":0},"rhys":{"jobs":0,"drinkUntil":0},"jay":{"jobs":0,"drinkUntil":0}}}},"view":"farm","mode":"tend","inventory":{"carrot":5,"wheat":3,"strawberry":2,"corn":0,"tomato":0,"lavender":0,"pumpkin":0,"apple":0,"mushroom":0,"egg":1,"milk":0},"animals":[],"seen":1793385794570,"orderIndex":3,"orientation":"auto","friendCode":"MEADOW-START","farmerName":"Temporary starter","sharedPantryVersion":1,"collectionState":{"owned":[]},"homestead":{"stats":{},"claimed":[]},"almanac":{"seen":{"carrot":true,"wheat":true,"strawberry":true,"egg":true},"totals":{},"claimed":[]},"farmLife":{"festivals":[],"ribbons":{},"collectionClaims":[]},"farmProgress":{"farms":{"willow":{"active":null,"changedAt":0,"practice":{"harvest":0,"care":0,"craft":0},"ranks":{}}},"relationships":[],"heard":{},"seasonSales":{},"completed":[]},"artisanMastery":{"version":1,"batches":{"flour":0,"bread":0,"jam":0,"cheese":0,"honeycake":0,"yarn":0,"soap":0,"bouquet":0,"applepreserve":0,"goatcheese":0,"scarf":0,"butter":0,"mushroomsoup":0,"berrytart":0,"applepie":0,"blanket":0,"giftbasket":0},"claimed":{},"signature":{}},"journey":{"projects":{},"customers":{},"training":{},"stats":{},"fair":{"2026-10-26":{"entries":{},"claimed":[]}},"finds":{},"discovered":{},"heard":{},"nursery":{"tier":0,"jobs":[],"pairs":{},"raised":0},"greenhouse":{"tier":0,"beds":[]},"version":1,"sharedLandmarks":[]},"workforce":{},"cropMastery":{"tiles":{}},"minigames":{"records":{},"rewards":{}},"club":{"queue":[],"applied":[],"pending":{}},"tutorial":{"version":1,"completed":[],"rewarded":[],"seenContexts":[],"started":false,"paused":false},"journal":{"day":"2026-10-31","progress":{},"claimed":[],"bonus":false}}$starter$::jsonb;rules text:='3910c7133b0a26b81d916343dca329b98831b3971edd3676a767f1fc65780991';rev bigint;digest text;
begin
 insert into auth.users(id,aud,role,is_anonymous) values(u,'authenticated','authenticated',true),(v,'authenticated','authenticated',true);
 insert into public.meadow_market_profiles(user_id,friend_code,display_name) values(u,'MEADOW-START','Temporary starter'),(v,'MM-'||left(v::text,8),'Temporary review');
 body:='{"expected_revision":0,"commands":[{"type":"farm.initialize"}]}';
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 r:=public.meadow_market_read_farm_command(u,request,body);if r->>'enabled'<>'false' then raise exception 'New-farm rollout was enabled';end if;
 insert into meadow_private.farm_command_accounts(user_id) values(u);
 r:=public.meadow_market_read_farm_command(u,request,body);if r->>'initializing'<>'true' or r#>>'{profile,friend_code}'<>'MEADOW-START' then raise exception 'Enrolled starter was unavailable';end if;
 r:=public.meadow_market_commit_farm_command(u,request,body,starter,jsonb_build_object('rules',rules,'results','[{"type":"farm.initialize","initialized":true}]'::jsonb,'events','[]'::jsonb,'help','[]'::jsonb,'market_sales','[]'::jsonb));
 if r->>'ok'<>'true' or (r->>'revision')::int<>1 or r#>>'{save_data,coins}'<>'250' then raise exception 'Server starter did not commit exactly once';end if;
 if not exists(select 1 from public.meadow_market_saves where user_id=u and save_protocol=4) or not exists(select 1 from meadow_private.farm_origins where user_id=u and origin='server_initial') or not exists(select 1 from meadow_private.farm_economy_journal where user_id=u and lane='server_initial') then raise exception 'Starter provenance/protocol missing';end if;
 r:=public.meadow_market_read_farm_command(u,request,body);if r->>'replayed'<>'true' then raise exception 'Lost starter reply was not replayable';end if;
 r:=public.meadow_market_read_farm_command(u,gen_random_uuid(),body);if r->>'conflict'<>'true' then raise exception 'Second starter could reset farm';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 r:=public.meadow_market_commit_economy_save(0,'{"version":1,"coins":777,"level":4,"xp":3,"active":"willow","_serverWorkers":{"forged":true},"farms":{"willow":{"objects":[],"inventory":{"carrot":12}}}}',gen_random_uuid());
 select revision,encode(sha256(convert_to(save_data::text,'UTF8')),'hex') into rev,digest from public.meadow_market_saves where user_id=v;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 r:=public.meadow_market_convert_reviewed_farm(v,review,rev,repeat('0',64),rules,'Disposable beta opening-balance test');if r->>'conflict'<>'true' then raise exception 'Stale review hash was accepted';end if;
 if exists(select 1 from meadow_private.farm_command_accounts where user_id=v) then raise exception 'Rejected review enrolled farm';end if;
 r:=public.meadow_market_convert_reviewed_farm(v,review,rev,digest,rules,'Disposable beta opening-balance test');
 if r->>'ok'<>'true' or r->>'save_protocol'<>'4' or r#>>'{save_data,coins}'<>'777' or r#>>'{save_data,farms,willow,inventory,carrot}'<>'12' or r->'save_data'?'_serverWorkers' then raise exception 'Conversion changed reviewed wealth or retained worker leases';end if;
 if not exists(select 1 from meadow_private.farm_origins where user_id=v and origin='reviewed_beta' and source_revision=rev and source_hash=digest) then raise exception 'Beta origin was presented as verified earnings';end if;
 r:=public.meadow_market_convert_reviewed_farm(v,review,rev,digest,rules,'Disposable beta opening-balance test');if r->>'replayed'<>'true' then raise exception 'Review replay was not idempotent';end if;
 if has_function_privilege('authenticated','public.meadow_market_convert_reviewed_farm(uuid,uuid,bigint,text,text,text)','EXECUTE') then raise exception 'Players can convert their own farm';end if;
end $$;
